/* Concept explanations, aligned to course-material/iitm-master-course-compendium.md.
   Every concept has core fields (l1, l2, take, aid, hr, mistake). Priority concepts have the full record:
   l3, l4, why, how, biz, analogy, ex, gen, mistakes, risks, confused, tools, notWhen, exercise, predict, allied, cvp.
   Level 1 is the tutor's plain-language explanation; Level 2 states the course concept; Levels 3–4 extend it. */
window.GMB = window.GMB || {};

GMB.DETAIL = {
/* ===== Week 1 ===== */
"C01.1": { l1: "AI is the broad goal of machines doing tasks that need intelligence. Machine learning (ML) is AI that learns patterns from data. Deep learning (DL) is ML using large neural networks. Generative AI (GenAI) is deep learning that creates new text, images or code.",
  l2: "Most HR tech you buy is predictive ML (scores, rankings, attrition risk). GenAI tools draft, summarise and converse. Knowing which one a vendor sells tells you what evidence to ask for: accuracy metrics for predictive tools, output-review processes for generative ones.",
  take: "AI ⊃ ML ⊃ DL ⊃ GenAI. Predictive models classify or forecast; generative models create new content.", aid: "Nested boxes: AI holds ML, ML holds DL, DL holds GenAI.",
  hr: "An attrition-risk score is predictive ML. A tool that writes the stay-interview guide is GenAI.", mistake: "Calling every analytics feature 'GenAI' and evaluating it the wrong way." },
"C01.2": { l1: "AI is worth it when the time it saves, valued at what that time costs, is bigger than what it costs to run and check.",
  l2: "Hard ROI: Hours Saved per Task × Frequency × Labour Rate = Gross Savings. Soft ROI: output standardisation, reduced cognitive load and burnout, faster turnaround. Present both; leaders fund hard ROI and remember soft ROI.",
  take: "Hard ROI = hours saved per task × frequency × labour rate; soft ROI = standardisation, lower cognitive load, faster turnaround.", aid: "Hours × how often × rate, then the soft wins.",
  hr: "Interview summaries: 0.5 h saved × 60 interviews a week × ₹1,200/h ≈ ₹36,000 a week gross, before review time.", mistake: "Quoting gross savings and forgetting review and maintenance effort (that's net ROI, Week 5)." },
"C01.3": { l1: "List your recurring tasks, then start with the ones where AI would help a lot and would be easy to introduce.",
  l2: "The course's Impact–Effort Matrix puts high-impact, low-effort tasks first for initial rollout. The brochure adds a sort into Automate / Accelerate / Augment / Avoid AI so you also decide how AI should be involved.",
  l3: "Inputs per task: frequency, time per task, judgement needed, data sensitivity, error cost. Impact = time × frequency × value of quality; effort = data readiness, tool availability, change management, risk tier. Quick wins (high impact, low effort) go first; high-impact, high-effort items become planned projects; low-impact items wait.",
  l4: "Effort includes governance effort: a Tier 3 use case carries approval and audit overhead that can turn an apparent quick win into a project. Re-plot after each pilot because effort drops as the toolkit matures.",
  why: "Most failed AI pilots chose the wrong task, not the wrong tool.", how: "List tasks → estimate impact and effort → plot → pick 1–2 quick wins → write a 1-page proposal (C01.9).",
  biz: "The opening move of any AI consulting engagement: a task-level opportunity map.", analogy: "Picking the low-hanging fruit that is also the ripest.",
  ex: "A TA team plots 25 tasks; interview-feedback summaries land in high impact, low effort; a full sourcing agent lands in high impact, high effort.",
  hr: "Quick wins: JD first drafts, feedback summaries, campus-drive emails. Projects: policy assistant, status automation. Avoid AI as decision-maker: final selection.",
  gen: "Finance: variance-commentary drafts are a quick win; automated reconciliations are a project.",
  mistakes: ["Starting from a tool instead of a task", "Ignoring governance effort when estimating effort"],
  risks: ["Quick wins that touch Tier 3 data"],
  confused: [["C05.1", "C01.3 prioritises where AI helps; C05.1's quick test decides whether a process should be automated."]],
  tools: ["Spreadsheet task inventory", "Any chat assistant to brainstorm tasks"], notWhen: ["A single obvious task where the decision is already made"],
  exercise: "List ten tasks from your last two weeks. Rate impact and effort 1–5, plot them, and name your two quick wins.",
  predict: { q: "High impact, but it needs Tier 3 approvals and new data feeds. Quick win?", a: "No. High effort, so it's a planned project. Quick wins are high impact and low effort." } },
"C01.4": { l1: "AI writes by predicting likely next words. That makes it fluent, but fluent isn't the same as correct.",
  l2: "Generative AI is not a deterministic factual database or an autonomous decision-maker. It works by probabilistic next-word prediction from patterns in training data, so it can produce plausible, authoritative-sounding text that is ungrounded (hallucination).",
  take: "GenAI predicts probable text; it is neither a factual database nor a decision-maker. Fluency does not equal accuracy.", aid: "Fluent is not factual.",
  hr: "An assistant states your notice-period policy confidently and wrongly, because it predicted typical policy wording.", mistake: "Treating a confident tone as evidence of accuracy." },
"C01.5": { l1: "Not every AI use is equally risky. The course sorts uses into three tiers and gives each tier a matching level of checking.",
  l2: "Tier 1, Drafting & Ideation: low impact, easily reversible (brainstorming, notes, internal email copy); the user is accountable with light spot-checking. Tier 2, Internal Analysis & Reporting: medium impact, cross-team visibility (internal dashboards, status updates, variance analyses); mandatory peer or managerial review. Tier 3, External & Decision-Critical: direct financial, legal, customer or regulatory risk; mandatory multi-stage human approval and audit logging.",
  l3: "Use the tier to set design requirements: Tier 1 → personal checklist (C01.8); Tier 2 → named reviewer before circulation; Tier 3 → approval gates (C05.3), audit log (C05.2) and only tools scoring Safety ≥ 4 (C04.2). Classify by the output's use, not the tool.",
  l4: "The same task can change tier: a candidate email draft is Tier 1 until it is sent, then Tier 3. Recruitment decisions sit firmly in Tier 3 and are also high-risk under the EU AI Act (EXT). Over-tiering kills ROI; under-tiering creates incidents.",
  why: "It decides how much review, logging and tool safety each use case needs.", how: "Ask: who sees the output, can it be reversed, does it touch money, law, customers or candidates? Assign the tier, then apply its controls.",
  biz: "A shared language that lets leaders approve AI use quickly without one-size-fits-all rules.", analogy: "Hospital triage: the colour decides how fast and by whom you're seen.",
  ex: "Brainstorming employer-brand slogans: Tier 1. Weekly TA status dashboard for leadership: Tier 2. Offer letters and rejection emails: Tier 3.",
  hr: "AI shortlisting that affects which candidates progress is Tier 3: multi-stage human approval and audit logging.",
  gen: "Finance: internal variance commentary is Tier 2; figures in an investor deck are Tier 3.",
  mistakes: ["Classifying by tool rather than by how the output is used", "Forgetting a draft becomes Tier 3 once it's sent externally"],
  risks: ["Rubber-stamp reviews that meet the rule but not its purpose"],
  confused: [["C01.7", "The tier sets oversight; the Cost–Latency–Accuracy triangle sets performance trade-offs."]],
  tools: ["Risk register", "Approval steps in automation tools"], notWhen: [],
  exercise: "Assign a tier to five of your AI uses and write the required control for each.",
  predict: { q: "An AI-drafted internal status update goes to three departments. Which tier?", a: "Tier 2: internal reporting with cross-team visibility. It needs peer or managerial review before use." },
  allied: [{ t: "NIST AI RMF: Govern, Map, Measure, Manage", s: "The course's first reference. A framework for organising AI risk work; the 3-tier model is a practical way to apply its 'Map' and 'Manage' functions.", src: "EXT" }] },
"C01.6": { l1: "'Shadow AI' is people using AI tools on their own, untracked. The course moves that into a governed setup.",
  l2: "From ad-hoc, untracked Shadow AI to an enterprise-governed AI operating model: approved tools, data rules, review and shared logging.",
  take: "Shift from untracked Shadow AI to a governed operating model with approved tools, data rules and logging.", aid: "Bring AI out of the shadows.",
  hr: "Recruiters pasting CVs into personal chatbots is Shadow AI; an approved assistant with redaction rules and logging is governed.", mistake: "Banning AI outright, which pushes use further into the shadows." },
"C01.7": { l1: "You usually can't have AI that is cheap, instant and highly accurate all at once. Improve one and another suffers.",
  l2: "The Cost–Latency–Accuracy Triangle: instant chat prioritises latency and cost over deep accuracy; legal review demands high accuracy and accepts higher latency and specialised cost.",
  l3: "Use it to set requirements per use case: candidate-facing chat needs low latency (assistant < 30 s, Week 10) with grounded accuracy; offer letters favour accuracy; bulk tagging favours cost. Each choice drives model, retrieval and review design.",
  l4: "Techniques shift the frontier rather than escape it: retrieval and caching raise accuracy cheaply; routing simple queries to smaller models lowers cost (EXT). Every extra review layer raises latency.",
  why: "It forces you to state what matters most before choosing tools.", how: "For each use case, rank cost, latency and accuracy; design to the top priority.",
  biz: "Prevents paying for accuracy you don't need, or shipping speed you can't trust.", analogy: "Good, fast, cheap: pick two.",
  ex: "A support chatbot optimises latency; a contract reviewer optimises accuracy.", hr: "Interview-slot chatbot: latency. Compensation answers: accuracy.", gen: "Marketing copy variants: cost. Regulatory filings: accuracy.",
  mistakes: ["Asking for maximum accuracy everywhere"], risks: ["Hidden latency from review steps"],
  confused: [["C02.4", "The triangle has three dimensions; the six decision pillars add risk, trust and scalability."]],
  tools: [], notWhen: [],
  exercise: "Place three TA use cases on the triangle and say which corner each optimises.",
  predict: { q: "A candidate FAQ bot must answer in seconds but never misstate policy. How do you resolve the tension?", a: "Keep latency low and get accuracy from grounding in policy documents (retrieval), not from a slow human review of every answer; escalate edge cases." } },
"C01.8": { l1: "Two short checklists: one before you send anything to AI, one before you use what comes back.",
  l2: "60-Second Pre-Flight Checklist: (1) remove sensitive details and PII, (2) define the explicit purpose, (3) set format and tone, (4) identify the designated human reviewer, (5) confirm the downstream use. 5-Step Manual Verification Protocol: compare with trusted internal sources, spot-check numbers independently, request step-by-step reasoning, rephrase and compare outputs, validate compliance and tone.",
  l3: "Pre-flight is an input control; verification is an output control. Scale verification to the risk tier: Tier 1 may need one or two steps; Tier 3 needs all five plus approval and logging.",
  l4: "Asking a model for step-by-step reasoning helps you spot gaps but isn't proof; independent sources and number checks carry more weight.",
  why: "These are the everyday controls that make individual AI use safe.", how: "Before: run the five pre-flight checks. After: run the verification steps the tier requires.",
  biz: "Cheap, teachable controls that reduce the most common AI errors.", analogy: "A pilot's pre-flight checklist and a landing checklist.",
  ex: "Before summarising a client report: strip names, state purpose, ask for a table, name the reviewer, note it goes to the CFO.",
  hr: "Before drafting a rejection email: remove candidate PII from the prompt, purpose = respectful decline, tone = warm, reviewer = recruiter, downstream = sent to candidate (Tier 3).",
  gen: "Finance: spot-check every figure in an AI-written variance note against the ledger.",
  mistakes: ["Skipping the 'designated reviewer' step", "Verifying by asking the same model 'are you sure?'"], risks: ["Checklist fatigue on high-volume tasks"],
  confused: [["C04.6", "The 30-second safe input checklist (Week 4) is the data-safety subset of the pre-flight checklist."]],
  tools: ["Checklist card", "Shared prompt log"], notWhen: [],
  exercise: "Take one AI output from this week. Run the pre-flight checklist retrospectively, then the five verification steps. What did you catch?",
  predict: { q: "Which pre-flight item most often gets skipped, and why does it matter?", a: "Naming the designated human reviewer. Without a named reviewer nobody owns the check, so Tier 2 and Tier 3 outputs slip through." } },
"C01.9": { l1: "A one-page case for an AI idea, so a leader can say yes or no quickly.",
  l2: "Six parts: Problem Statement, Proposed AI Solution, Expected Business Impact (ROI), Risk & Controls, Implementation Plan / Pilot Scope, Success Metrics.",
  take: "1-page proposal = problem, solution, impact/ROI, risk & controls, pilot scope, success metrics.", aid: "Problem, fix, pay-off, safety, pilot, proof.",
  hr: "Proposal: cut interview-feedback turnaround from 3 days to 1 using AI summaries; Tier 2; 4-week pilot with two teams; metric: turnaround and edit rate.", mistake: "Leaving out Risk & Controls, which is where leaders say no." },
/* ===== Week 2 ===== */
"C02.1": { l1: "An LLM writes one small piece of text (a token) at a time, each time picking a likely next piece based on everything before it.",
  l2: "Because it predicts likely text, wording and context strongly change the output. Give it the right context and it predicts the right kind of answer; leave gaps and it fills them with plausible guesses.",
  take: "LLMs generate text token by token by predicting a probable continuation of the context.", aid: "It predicts the next word, it doesn't look anything up.",
  hr: "'Write a JD' gives a generic JD; adding level, location, team and must-haves changes every predicted word.", mistake: "Assuming the model 'knows' your company because it sounds confident." },
"C02.2": { l1: "A model is first trained on huge amounts of public text, then tuned to follow instructions. It can only use what it learned plus what you put in the conversation.",
  l2: "Pre-training gives general knowledge up to a cut-off date. Instruction tuning makes it helpful. The context window limits how much it can read at once. Some models also handle images and audio.",
  take: "Knowledge = training data (to a cut-off) + what is in the context window.", aid: "Trained memory plus the page in front of it.",
  hr: "It won't know a labour-law change from last month unless you provide the text.", mistake: "Expecting a model to know recent or private information." },
"C02.3": { l1: "AI outputs go wrong in three typical ways: they stop short, they wander off the brief, or they make things up.",
  l2: "The three failure modes: Incomplete Output (cuts off or skips required steps); Drift (tone, format or instruction adherence degrades mid-response); Hallucination (confident fabricated claims unsupported by data).",
  l3: "Each mode has a different fix. Incomplete: split the task, specify every required section, raise length limits. Drift: tighten rules and output format, shorten the task, add examples. Hallucination: ground in sources, add a missing-information rule, verify (C01.8, C11.4). Week 10's escalation matrix adds the response: stop on hallucination, correct and re-run on drift.",
  l4: "Modes interact: overloaded tasks produce both incomplete output and drift. Hallucination can be reduced, not eliminated; grounding turns 'made up' into 'misread or mis-retrieved', which citations make detectable.",
  why: "Naming the failure tells you which knob to turn.", how: "Read the output → name the mode → apply the matching fix → retest.",
  biz: "Gives teams a shared vocabulary for AI quality problems.", analogy: "A new joiner who stops halfway, drifts off-brief, or bluffs.",
  ex: "A 12-section report returns 9 sections (incomplete); the last third switches to casual tone (drift); it cites a study that doesn't exist (hallucination).",
  hr: "Interview-kit prompt: misses two competencies (incomplete); later questions ignore the 'behavioural only' rule (drift); invents a company value (hallucination).",
  gen: "Sales proposal that quotes a discount tier the company never offered: hallucination.",
  mistakes: ["Calling every error a hallucination", "Adding 'be accurate' and expecting facts to appear"],
  risks: ["Fabricated policy statements reaching candidates"],
  confused: [["C02.6", "C02.3 names what went wrong; C02.6's prompt knobs are how you fix it."]],
  tools: ["Test-case bank", "Citation checks"], notWhen: [],
  exercise: "Collect three bad AI outputs from your work. Label each as incomplete, drift or hallucination and name one fix.",
  predict: { q: "A long policy summary starts formal and ends chatty, ignoring the 'no bullet points' rule. Which failure mode?", a: "Drift: tone and instruction adherence degraded mid-response. Tighten rules, shorten the task or add an example." },
  allied: [{ t: "Grounding and faithfulness evaluation", s: "Measuring whether each claim is supported by provided sources turns hallucination into a testable metric.", src: "ALLIED" }] },
"C02.4": { l1: "When choosing or running an AI system, weigh six things: what it costs, how fast it is, how accurate, how risky, how much people trust it, and whether it can scale.",
  l2: "Six decision pillars: Cost, Speed, Accuracy, Risk, Trust, Scalability. Governed systems bound AI capability with business constraints, verification layers and clear accountability.",
  take: "Manage AI systems across Cost, Speed, Accuracy, Risk, Trust and Scalability.", aid: "CSA-RTS: cost, speed, accuracy; risk, trust, scale.",
  hr: "A CV-tagging model: cheap and fast, accuracy acceptable, risk Tier 2, trust built through sampling, scales to 5,000 CVs.", mistake: "Comparing tools on accuracy alone." },
"C02.5": { l1: "A five-line way to explain an AI choice to a leader.",
  l2: "Executive Justification Framework: Problem → Choice → Value → Risk Control → Owner.",
  l3: "Problem: the business pain in numbers. Choice: which stack category and tool, and why not the alternatives. Value: hard and soft ROI. Risk Control: tier and controls. Owner: the accountable person after go-live.",
  l4: "The Owner line is what most proposals miss; without it, nobody maintains prompts, data or reviews and the system decays.",
  why: "Leaders approve choices they can repeat to their own boss.", how: "Write one sentence per element.",
  biz: "Use it in every steering-committee update.", analogy: "A doctor's note: diagnosis, treatment, benefit, side-effects, who follows up.",
  ex: "Problem: 600 policy emails a month. Choice: document-grounded assistant, not a chatbot, because answers must cite policy. Value: 40 h/month. Risk control: Tier 2, citations, HRBP escalation. Owner: HR Ops lead.",
  hr: "Justify a candidate follow-up automation using the five lines.", gen: "Justify an AI invoice-matching workflow to the CFO.",
  mistakes: ["No owner named", "Choice without alternatives considered"], risks: [], confused: [["C01.9", "The 1-page proposal (Week 1) is the full case; the justification framework is the five-line executive version."]],
  tools: [], notWhen: [], exercise: "Write the five lines for an AI use case you want to pitch this quarter.",
  predict: { q: "Which of the five elements stops an AI system from decaying after launch?", a: "Owner: an accountable person who maintains prompts, data and reviews." } },
"C02.6": { l1: "Five dials control AI output quality: how good the context is, how clear the instruction is, the do's and don'ts, examples, and temperature.",
  l2: "Prompt knobs: context quality, instruction clarity, negative/positive constraints, concrete examples, temperature (low for reliable extraction, higher for creative ideation).",
  take: "Control outputs with context quality, instruction clarity, constraints, examples and temperature.", aid: "Context, clarity, constraints, cases, temperature.",
  hr: "Feedback summaries miss competencies → improve context (attach the competency framework) and add a positive constraint (one line per competency).", mistake: "Turning several knobs at once so you can't tell what worked." },
"C02.7": { l1: "Business AI tools come in five families, from flexible-but-loose to powerful-but-needing-control.",
  l2: "The Business AI Stack: Chat Interfaces (fast, low control), Search & Knowledge (grounded, reliable), Automation Platforms (scalable, rule-driven), Analytics & Insights (pattern detection), Agent Frameworks (multi-step, high governance needed). Core tensions: Accuracy vs Speed, Cost vs Scale, Flexibility vs Control, Power vs Risk.",
  l3: "Map needs to categories: one-off thinking → Chat; answers from documents → Search & Knowledge; repeatable steps → Automation; numbers → Analytics; multi-step goals with tools → Agents. Moving down the list adds power and governance burden.",
  l4: "Real solutions combine categories (automation with an AI step, assistant with retrieval). Choose the least powerful category that meets the need: Power vs Risk.",
  why: "Choosing the category is the biggest architecture decision.", how: "State the need → pick the least powerful category that meets it → name the tension you accept.",
  biz: "Stops 'let's build an agent' when a search assistant would do.", analogy: "From a pocket calculator to an autopilot: more power, more checks.",
  ex: "Policy questions → Search & Knowledge; weekly pipeline report → Automation.", hr: "Candidate scheduling across calendars with rebooking → Agent Framework with approval.", gen: "Sales forecast anomalies → Analytics & Insights.",
  mistakes: ["Jumping to agents for fixed steps"], risks: ["Agent frameworks without governance"],
  confused: [["C13.1", "The stack groups tools by category; C13.1 distinguishes system behaviours (chatbot, assistant, automation, agent, multi-agent)."]],
  tools: ["ChatGPT/Claude", "NotebookLM", "n8n/Zapier", "Looker Studio", "Agent builders"], notWhen: [],
  exercise: "Assign five TA problems to a stack category and name the tension each choice accepts.",
  predict: { q: "Which category trades the most power for the most governance need?", a: "Agent Frameworks: multi-step and powerful, so high governance is needed." } },
"C02.8": { l1: "AI costs more than the licence. Usage grows, people spend time reviewing, and connections need upkeep.",
  l2: "Hidden cost drivers: token consumption scaling with adoption, human review bottlenecks, integration maintenance.",
  take: "Hidden costs: token use grows with adoption, review bottlenecks, integration maintenance.", aid: "Tokens, reviewers, plumbing.",
  hr: "A pilot with 5 recruiters costs little; rolled out to 120 with Tier 2 reviews, review time becomes the biggest cost.", mistake: "Budgeting from pilot usage." },
/* ===== Week 3 ===== */
"C03.1": { l1: "Zero-shot: just ask. Few-shot: show a few examples first.",
  l2: "Zero-shot suits low-risk creative brainstorming and open exploration where format flexibility is fine. Few-shot is mandatory for medium-to-high risk, compliance-critical, brand-voice-sensitive or multi-user reusable templates; examples act as micro-training data for tone, structure and boundaries. Poor examples cause overfitting to one format, ignoring edge cases, or copying outdated policy.",
  take: "Zero-shot for low-risk exploration; few-shot is mandatory for medium/high-risk, compliance, brand voice and reusable templates.", aid: "Low risk, just ask; real risk, show examples.",
  hr: "Rejection emails (Tier 3, brand voice): few-shot with two approved examples. Brainstorming campus-event ideas: zero-shot.", mistake: "Using one example only, so every output copies its format and misses edge cases." },
"C03.2": { l1: "COSTAR is a checklist for a prompt brief: Context, Objective, Style, Tone, Audience, Response.",
  l2: "COSTAR comes from your notes. It doesn't appear in the course compendium, which teaches Role · Context · Rules · Output Format (C03.3). COSTAR is a useful completeness check for audience-facing writing.",
  take: "COSTAR = Context, Objective, Style, Tone, Audience, Response. In the exam, lead with the course's Role · Context · Rules · Output Format.", aid: "COSTAR covers framing; the course's Rules slot covers the limits.",
  hr: "Campus-drive invite: context (40 graduate engineers, Pune), objective (schedule a drive), style, warm tone, TPO audience, 150-word email.", mistake: "Using COSTAR without rules, so nothing stops invented dates or CTCs.",
  cvp: "Course compendium: Role · Context · Rules · Output Format. Your notes: COSTAR. They overlap on Context and Output; COSTAR adds Style, Tone and Audience, while the course adds Role and Rules (constraints and fallbacks). Use the course structure in the exam and combine both at work." },
"C03.3": { l1: "The course treats a prompt as a control system with four parts: who the AI should act as, what it needs to know, what rules it must follow, and exactly what to deliver.",
  l2: "Role: identity, domain perspective and expertise boundary. Context: operating domain, background facts and source material. Rules: explicit boundaries, negative constraints and fallback instructions. Output Format: the exact deliverable (tables, bullets, JSON schema). AI initiatives rarely fail on the model; they fail on poor instructions, no standards, no testing and no reuse.",
  l3: "Rules carry the fallback: 'If information is missing, say so and list what you need.' Context should name its sources and delimit pasted data so it isn't read as instructions. Output Format should be specific enough for a reviewer or an automation to check.",
  l4: "Role sets an expertise boundary as well as a voice: 'You are a recruitment coordinator; you do not give legal advice.' Too much context dilutes attention and costs tokens; Rules that conflict cause drift.",
  why: "Prompt design is the primary behavioural control layer for consistency, compliance and reliability.", how: "Write the four parts explicitly, in order, with data clearly delimited.",
  biz: "A team standard that makes prompts reviewable and reusable.", analogy: "A job description: role, background, house rules, deliverable.",
  ex: "Role: HR policy analyst. Context: Leave Policy v4 (pasted). Rules: answer only from the policy; no legal advice; if not covered, say 'Not covered — contact HR Ops'. Output: answer + section citation.",
  hr: "Interview-kit prompt: Role = structured-interview designer; Context = role, level, competencies; Rules = behavioural questions only, nothing on age, family or religion; Output = table of 8 questions with scoring guide.",
  gen: "Sales: Role = proposal writer; Context = product sheet and price book; Rules = no discounts beyond the price book; Output = one-page proposal template.",
  mistakes: ["No Rules, so nothing stops invention", "Role without an expertise boundary", "Output Format as 'be detailed'"],
  risks: ["Instructions hidden in pasted data taking over"],
  confused: [["C03.2", "COSTAR (your notes) covers style, tone and audience; the course's four parts add Role and Rules."]],
  tools: ["Any LLM", "Prompt libraries"], notWhen: [],
  exercise: "Rewrite a prompt you used this week into Role · Context · Rules · Output Format. What did the Rules section add?",
  predict: { q: "Where does 'If the policy doesn't cover it, say so' belong?", a: "In Rules: it's a fallback instruction." },
  allied: [{ t: "Context engineering", s: "Current industry term (a course reference, Anthropic 2024) for choosing everything that enters the model's context: instructions, documents, memory, tool results. Extends the Context component.", src: "EXT" }, { t: "Prompt injection", s: "Text inside inputs (for example a CV) can try to override your Rules. OWASP lists it as the top LLM risk.", src: "EXT" }] },
"C03.4": { l1: "When a prompt fails, find out which kind of failure it is, change one thing, and test again.",
  l2: "Prompt Failure Taxonomy: missing context, ambiguous goals, absent constraints, unclear output format, task overloading. Systematic debugging loop: (1) test, (2) observe output, (3) identify the exact failure point, (4) adjust one variable at a time, (5) retest to verify improvement.",
  l3: "Map taxonomy to fixes: missing context → add sources; ambiguous goal → one explicit objective; absent constraints → add rules and fallbacks; unclear format → schema; task overload → split into a chain. Record each change in a Before/After capture (C03.9).",
  l4: "Changing one variable at a time is slower but is the only way to know what worked; with temperature above zero, rerun each version more than once before concluding.",
  why: "It turns prompt fixing from guesswork into a repeatable method.", how: "Test → observe → identify → adjust one variable → retest.",
  biz: "Makes prompt quality improvement auditable.", analogy: "A mechanic changing one part at a time.",
  ex: "A summary skips risks: failure type 'unclear output format'; add a required 'Risks' section; retest.",
  hr: "Sourcing-message prompt gives generic messages: 'missing context' (no candidate profile fields); add them; retest.",
  gen: "A finance analysis that mixes three asks fails from task overloading; split it.",
  mistakes: ["Changing role, rules and format all at once", "Declaring success after one good run"], risks: [],
  confused: [["C02.3", "Failure modes describe the output (incomplete, drift, hallucination); the taxonomy describes the prompt's cause."]],
  tools: [], notWhen: [], exercise: "Take a failing prompt, name its taxonomy category, change one variable and record before/after.",
  predict: { q: "A prompt asks for a summary, a risk list, an email and a slide outline in one go and does all four poorly. Category?", a: "Task overloading. Split it into separate prompts or a chain." } },
"C03.5": { l1: "Ask the AI to answer in a fixed shape (a table, set headings or a list of fields) so people and other tools can use it easily.",
  l2: "Output Format is one of the course's four prompt components: the exact structural deliverable, from tables to a JSON schema. Structured outputs let an AI step feed the next step of an automation or an agent handoff.",
  l3: "Specify field names, types and allowed values; give a schema or example object; include 'unknown' or 'not found' fields. Many model APIs can enforce a JSON schema (course reference: OpenAI structured outputs).",
  l4: "Rigid schemas can force the model to fill fields it has no evidence for, so always allow null or unknown, and validate before the next step uses the output.",
  why: "Unstructured text is the most common reason AI steps break automations.", how: "Define fields → give an example → require unknowns to be marked → validate.",
  biz: "Turns AI from a writing aid into a process component.", analogy: "A form instead of a free-text letter.",
  ex: "Meeting notes returned as {decisions[], actions[{owner, due}], risks[]}.", hr: "Interview feedback → {candidate_id, competency_scores{}, evidence[], recommendation: hire | no_hire | unsure}.", gen: "Support tickets → {category, urgency, product, summary}.",
  mistakes: ["No 'unknown' option", "Field names that change between runs"], risks: ["The model invents values to fill required fields"],
  confused: [["C03.6", "Structured outputs fix the shape; temperature tunes randomness."]], tools: ["JSON mode / structured outputs", "n8n output parser"], notWhen: ["Exploratory writing"],
  exercise: "Design a JSON output for an interview-loop summary with at least one field that must say 'unknown' when evidence is missing.",
  predict: { q: "Why must a schema include an 'unknown' option?", a: "Without it the model is pushed to invent a value for every field." } },
"C03.6": { l1: "Temperature controls how predictable or creative the AI is.",
  l2: "Low temperature for reliable extraction and consistent formats; higher temperature for creative ideation.",
  take: "Low temperature for reliable extraction; higher for creative ideation.", aid: "Cold for facts, warm for ideas.",
  hr: "Extracting skills from CVs: low. Employer-brand taglines: higher.", mistake: "Using high temperature for policy answers." },
"C03.7": { l1: "Don't paste personal or confidential information into AI tools that aren't approved for it.",
  l2: "Replace names with IDs, remove salary and health details, and use only approved tools for sensitive work (see the 30-second safe input checklist, C04.6).",
  take: "Minimise and anonymise data in prompts; use approved tools; avoid risky phrasing.", aid: "Strip it before you ship it.",
  hr: "'Summarise Priya Sharma's interview; she's 42' → 'Summarise Candidate C-104's interview against the competency framework.'", mistake: "Pasting full CVs with contact details into a consumer chatbot." },
"C03.8": { l1: "Prompting skill grows in five stages, from casual chatting to designing reusable prompt systems.",
  l2: "Prompt Maturity Curve: L1 Chatting (informal, unpredictable); L2 Formatting (headings, simple templates); L3 Structuring (explicit roles, detailed deliverables, defined audiences); L4 Testing (edge cases, ambiguity checks, error analysis); L5 System Design (reusable blueprints with automated self-checking and governance ownership).",
  take: "Chatting → Formatting → Structuring → Testing → System Design.", aid: "Chat, format, structure, test, system.",
  hr: "Most recruiters sit at L1–L2. A shared, tested interview-kit blueprint with an owner is L5.", mistake: "Thinking a well-structured prompt (L3) is production-ready without testing (L4)." },
"C03.9": { l1: "Keep a set of test inputs for each prompt, and record what changed and why it's better.",
  l2: "Starter test-case bank: Easy/Standard cases, Boundary/Edge cases, High-Risk/Failure cases. Before/After Capture Template: baseline output, refined prompt, failure type, risk reduction, business impact.",
  take: "Test every prompt on standard, edge and high-risk cases; capture before/after with failure type, risk reduction and impact.", aid: "Easy, edge, explosive; before and after.",
  hr: "JD-rewrite prompt tests: standard role; vague hiring-manager brief (edge); a brief with discriminatory requirements (high-risk).", mistake: "Testing only the happy path." },
"C03.10": { l1: "Turn a good prompt into a reusable template: the fixed parts stay, the changing details become fill-in fields, and the AI checks its own work before answering.",
  l2: "Reusable Prompt Blueprint: Fixed Control Logic (role, grounding rules, output schema, built-in self-validation steps) + Variable Inputs (parameterised fields such as {Project Name}, {Date}, {Progress}) + Self-Checking Outputs (the model audits completeness, visible assumptions and low-confidence flags before the final answer).",
  l3: "Variables make the prompt safe to reuse across users and to drop into automations (the variables become data fields). Self-checks are an extra line such as: 'Before answering, list any required field you couldn't fill and flag low-confidence statements.'",
  l4: "Self-checks catch omissions but don't replace external verification; a model can confidently confirm its own error. Version blueprints and assign an owner (Maturity L5).",
  why: "Reuse plus standards is where AI quality scales.", how: "Separate fixed logic from variables → add a self-check → test → version → assign owner.",
  biz: "Prompt packs become team assets in the Everyday AI Toolkit (C04.7).", analogy: "A mail-merge letter with a built-in proofreader.",
  ex: "Weekly status blueprint with {Project}, {Week}, {Progress}, {Risks}; self-check flags missing risks.",
  hr: "Interview-kit blueprint with {Role}, {Level}, {Competencies}; self-check confirms every competency has two questions and none are unlawful.",
  gen: "Sales follow-up blueprint with {Client}, {Meeting date}, {Agreed actions}.",
  mistakes: ["Hard-coding details that should be variables", "No self-check"], risks: ["Blueprints copied without owners, then going stale"],
  confused: [["C03.3", "C03.3 is the structure of one prompt; the blueprint makes it reusable and self-checking."]],
  tools: ["Prompt libraries", "Automation AI steps"], notWhen: ["One-off exploratory prompts"],
  exercise: "Convert your best recruiter prompt into a blueprint with at least three {variables} and a self-check line.",
  predict: { q: "Which blueprint element makes it safe to drop into an automation?", a: "Variable inputs (data fields fill them) plus a fixed output schema." } },
"C03.11": { l1: "A short scorecard teams use to review each other's prompts before they're shared.",
  l2: "Peer Review Rubric, scored 1–5: Role/Task Definition, Constraint Strength, Validation Logic, Reusability, Scalability Readiness. Decision: Approve, Revise or Escalate.",
  take: "Score prompts 1–5 on role/task definition, constraint strength, validation logic, reusability, scalability readiness → Approve, Revise or Escalate.", aid: "Role, rules, checks, reuse, scale.",
  hr: "Before adding a rejection-email blueprint to the team library, a peer scores it; weak validation logic → Revise.", mistake: "Approving prompts on output quality from one run." },
/* ===== Week 4 ===== */
"C04.1": { l1: "AI tools come in families: chat assistants, writing tools, research tools, meeting note-takers, slide makers, automation platforms, analytics tools and assistant builders.",
  l2: "Map categories to your work before picking products. Week 2's Business AI Stack groups them by control and power.",
  take: "Categorise tools by job-to-be-done before comparing products.", aid: "Job first, tool second.", hr: "Meeting note-taker for intake calls; slide maker for QBRs; automation tool for reminders.", mistake: "Buying a tool for each task." },
"C04.2": { l1: "Choose tools on four questions: Is it valuable? Simple? Affordable? Safe? Safety can veto everything else.",
  l2: "Value (time reclaimed, errors reduced), Simplicity (onboarding, workflow friction), Cost (total cost of ownership), Safety (compliance, privacy, access control, auditability). A tool scoring < 4 on Safety is barred from Tier-2 and Tier-3 workflows.",
  take: "Score Value, Simplicity, Cost, Safety; Safety < 4 bars a tool from Tier-2 and Tier-3 work.", aid: "VSCS, and safety holds the veto.",
  hr: "A note-taker scores 5 on value but 3 on safety (recordings stored outside region): Tier 1 only, never for candidate interviews.", mistake: "Averaging the four scores so high value hides low safety." },
"C04.3": { l1: "Integrations are how tools pass information to each other automatically, through ready-made connectors, APIs or webhooks.",
  l2: "A connector is a pre-built link; an API is the door a system offers to other software; a webhook is a message one system sends when something happens.",
  take: "Connectors, APIs and webhooks let tools exchange data without copy-paste.", aid: "A webhook rings the bell; an API answers the door.", hr: "ATS sends a webhook when a candidate reaches 'Offer'; the automation reads details via the ATS API.", mistake: "Assuming every tool can connect to every other." },
"C04.4": { l1: "A simple operating model for team AI use: know which data can go where, always check outputs, and keep a shared log.",
  l2: "Minimum Viable Toolstack Operating Model. Data sensitivity tiers: Public (direct use permitted); Internal operational (only after redaction); Confidential/Regulated (strictly prohibited from external public models). Mandatory human verification: spot-check numbers, validate missing information, confirm tone, audit compliance language. Shared logging: archive prompts, outputs and human adjustments centrally.",
  take: "Three data tiers (public · internal after redaction · confidential prohibited), mandatory verification, shared logging.", aid: "Classify, verify, log.",
  hr: "Job ads: public. Requisition pipeline counts: internal, after redaction. Candidate CVs, offers, health data: confidential, never in public models.", mistake: "Treating 'internal' as safe without redaction." },
"C04.5": { l1: "A simple way to decide when to switch tools, so the team doesn't chase every launch.",
  l2: "Tool Change Radar: log triggers (feature releases, policy shifts, cost updates), evaluate workflow impact, assign an owner and review timeline. Switch only for proven cost/time savings, quality leaps or compliance requirements.",
  take: "Log triggers, assess impact, assign owner; switch only for proven savings, quality leaps or compliance.", aid: "Radar, not reflex.", hr: "A new AI sourcing feature launches: log it, pilot for two weeks with an owner, switch only if response rates improve.", mistake: "Switching after one demo." },
"C04.6": { l1: "Four quick checks before you paste anything into an AI tool.",
  l2: "30-Second Safe Input Checklist: No PII · Redacted numbers · Policy compliant · Approved tool.",
  take: "Before any prompt: no PII, redacted numbers, policy-compliant data, approved tool.", aid: "People, numbers, policy, platform.",
  hr: "Before asking AI to compare two offers: replace names with IDs, generalise CTC to bands, confirm comp data is cleared, use the enterprise tool.", mistake: "Redacting names but leaving exact salaries." },
"C04.7": { l1: "Raw AI output is a draft. Professional output is structured, complete, checked and clear about what to do.",
  l2: "Reliable outputs need Structure (tables, steps), Completeness (all required inputs), Accuracy Check (verified figures) and Clarity for Action (unambiguous recommendations). The Everyday Practical AI Toolkit = Core Tools + Prompt Packs + Output Templates + Quality Checklists.",
  take: "Reliable output = structure, completeness, accuracy check, clarity for action; toolkit = tools + prompt packs + templates + checklists.", aid: "Shape, whole, true, actionable.",
  hr: "A TA weekly update template with fixed sections, required numbers, a verification tick-box and a 'decisions needed' line.", mistake: "Forwarding unstructured AI output as finished work." },
/* ===== Week 5 ===== */
"C05.1": { l1: "Automate tasks that happen often, follow clear rules, waste time and matter, and that don't need much human judgement.",
  l2: "Automation sweet spot: high-frequency, repetitive, rule-based, data-driven tasks needing minimal judgement (status consolidation, order notifications, lead routing). Avoid: high-ambiguity decisions, complex contract interpretation, sensitive customer escalations, unowned processes. Use-case quick test (1–5 scale): automate only if (Frequency + Friction + Impact) ≥ 10 and Judgement Required ≤ 2.",
  l3: "Score each process on the four dimensions. Example: interview reminders F5 + Fr4 + I3 = 12, J1 → automate. Shortlisting F4 + Fr4 + I5 = 13 but J4 → don't automate the decision; automate data gathering around it. Then run the Go/No-Go gate (C05.6).",
  l4: "The judgement cap is the safety rule: high scores on value never override high judgement. Unowned processes fail the Go/No-Go gate even if they pass the quick test.",
  why: "Picking the wrong process wastes the build and erodes trust.", how: "Score F, Fr, I and J (1–5) → apply the rule → check the avoid list → Go/No-Go gate.",
  biz: "The core diagnostic in a process-improvement consulting offer.", analogy: "Only put a dish on the conveyor belt if the recipe never needs a chef's judgement.",
  ex: "Weekly status consolidation: F5 + Fr4 + I3 = 12, J1 → automate.",
  hr: "Candidate status updates pass; offer negotiation fails on judgement; background-check escalations are sensitive and on the avoid list.",
  gen: "Lead routing passes; contract interpretation is on the avoid list.",
  mistakes: ["Ignoring the judgement cap because the value score is high", "Automating an unowned process"],
  risks: ["Brittle automations on unstable processes"],
  confused: [["C01.3", "C01.3 prioritises opportunities by impact and effort; C05.1 decides whether a process qualifies for automation."]],
  tools: ["Scoring sheet"], notWhen: ["One-off tasks", "Processes under active redesign"],
  exercise: "Run the quick test on five TA processes. Which pass, and which fail on judgement?",
  predict: { q: "Frequency 5, Friction 4, Impact 4, Judgement 3. Automate?", a: "No. The sum is 13 (≥ 10) but Judgement 3 exceeds the cap of 2. Automate the surrounding data steps and keep the decision human." },
  cvp: "Your brief listed seven criteria (repetition, frequency, friction, impact, judgement, sensitivity, stability). The course formalises four into the quick test; sensitivity is handled by the risk tier and data clearance in the Go/No-Go gate." },
"C05.2": { l1: "Every automation, in any tool, has the same six layers: something starts it, it gathers and checks data, it processes, it applies conditions or approvals, it delivers outputs, and it records what happened.",
  l2: "Universal automation structure: Trigger → Data Inputs / Validation → Processing Steps → Conditions / Approvals → Outputs / Notifications → Audit Log. Governed layers include explicit owner assignment, conditional decision rules, approval checkpoints, execution logging and emergency rollback paths.",
  l3: "The AI step sits in Processing Steps (draft, classify, summarise) with a structured output (C03.5). Validation catches missing or malformed data before processing. Conditions/Approvals hold deterministic rules and human gates. The Audit Log records inputs, decisions, outputs and approvers.",
  l4: "Keep deterministic logic in Conditions, not inside AI prompts. Each layer is a failure point; pair it with the Fallback Ladder (C05.4). Rollback paths matter most when outputs change other systems.",
  why: "It is the course's tool-agnostic blueprint for every automation.", how: "Write the six layers for the manual process, then mark which are automated and who owns each.",
  biz: "A blueprint you can hand to any builder or client, regardless of tool.", analogy: "A relay race with a referee's record at the end.",
  ex: "New support email (Trigger) → extract and validate fields (Data) → AI drafts reply (Processing) → urgent? approval (Conditions) → reply queued (Output) → log (Audit).",
  hr: "Candidate moves to 'Interview' (Trigger) → candidate, panel, slot validated (Data) → AI drafts personalised invite (Processing) → panel confirmed and recruiter approves exceptions (Conditions) → email and calendar invite (Outputs) → record in audit log (Audit).",
  gen: "Invoice received → validate PO match → AI summarises exceptions → > $10,000 needs approval → notify AP → log.",
  mistakes: ["No audit log", "Rules buried inside the AI prompt", "No owner or rollback path"], risks: ["Silent failures when a layer breaks"],
  confused: [["C13.1", "An automation follows these fixed layers; an agent chooses its own next steps."]],
  tools: ["n8n", "Make", "Zapier", "Power Automate"], notWhen: ["Open-ended reasoning paths (consider an agent)"],
  exercise: "Map your weekly hiring-manager status update onto the six layers and name the owner of each.",
  predict: { q: "Where does 'invoice above $10,000 needs CFO sign-off' go?", a: "Conditions / Approvals: a deterministic threshold with an approval gate." },
  cvp: "Your brief used Trigger → Data → Decision → Integration → AI Step → Output. The course structure is Trigger → Data Inputs/Validation → Processing Steps → Conditions/Approvals → Outputs/Notifications → Audit Log. Integration happens inside the layers; the course adds validation and an audit log. Use the course order in the exam." },
"C05.3": { l1: "Rules send each case down the right path, and a person must approve anything high-impact before it happens.",
  l2: "Conditional logic routes paths on numerical thresholds (e.g. invoice > $10,000), completeness checks or SLAs. Approval gates prevent unverified automated execution of high-impact actions such as financial disbursements and external client updates.",
  take: "Route on thresholds, completeness and SLAs; put approval gates before high-impact actions.", aid: "Rules route, people approve.",
  hr: "Offer amount above band → HRBP approval; incomplete candidate record → route to recruiter; interview not confirmed in 24 h → reminder.", mistake: "Letting AI-drafted messages go straight to candidates." },
"C05.4": { l1: "When an automation fails, step down a ladder: try again, tell the owner, hand it to a person, or stop safely and record it.",
  l2: "Fallback Ladder: Retry (automated, exponential backoff, e.g. 3× over 5 minutes) → Notify Owner (Slack/email if retries fail) → Route to Manual (hand the payload to a human queue) → Safe Stop & Log (terminate without corrupting downstream data). The Human-in-the-Loop Control Matrix sets owners, response SLAs and action protocols for missing data, approval timeouts and integration errors.",
  l3: "Design per failure type: transient API errors → retry; persistent errors → notify and route; corrupt data → safe stop before writing. The HITL matrix is a table: exception × owner × SLA × action.",
  l4: "Retries must be safe to repeat (no duplicate emails or payments). Safe Stop protects downstream systems; a partial write is worse than no write.",
  why: "Automations fail; governed ones fail safely.", how: "For each failure type choose the ladder rung; document owner and SLA in the HITL matrix.",
  biz: "Fallbacks and owners are what make leaders trust automation.", analogy: "A lift that stops at the nearest floor and calls the engineer, rather than dropping.",
  ex: "CRM API down: retry 3× over 5 minutes → alert ops owner → queue the update for manual entry → log.",
  hr: "Calendar API fails while booking an interview: retry → notify coordinator → route to manual scheduling queue → log; candidate never gets a half-booked invite.",
  gen: "Payment file rejected: safe stop and log, no partial payments.",
  mistakes: ["Infinite retries", "Retries that send duplicate messages", "No named owner"], risks: ["Silent stalls with no notification"],
  confused: [["C13.8", "C05.4 handles workflow step failures; C13.8 adds agent-specific failures like infinite loops and misrouting."]],
  tools: ["n8n error workflows", "Make error handlers"], notWhen: [],
  exercise: "For a candidate follow-up automation, write the fallback ladder and a 3-row HITL control matrix.",
  predict: { q: "Retries failed and the payload is valid but the system is down. Next rung?", a: "Notify the owner, then route to the manual queue. Safe Stop is for when continuing could corrupt data." } },
"C05.5": { l1: "The same automation patterns work in every function.", l2: "A TA reminder flow becomes a finance invoice-reminder flow with different data and approvers.", take: "Automation patterns transfer across HR, Ops, Sales, Product, Finance and Marketing.", aid: "Same layers, different data.", hr: "Candidate follow-up → vendor follow-up.", mistake: "Rebuilding from scratch for each function." },
"C05.6": { l1: "Work out what the automation is really worth after running costs, and check five things before you build.",
  l2: "Annual Hours Saved × Hourly Labour Rate = Gross Productivity Value. Net Automation ROI = Gross Value − Operational Effort (maintenance, monitoring, API costs). Go/No-Go Feasibility Gate: measurable ROI, acceptable risk tier, designated process owner, rollback feasibility, data classification clearance.",
  take: "Net ROI = gross value − operational effort; build only if the Go/No-Go gate passes (ROI, risk tier, owner, rollback, data clearance).", aid: "Net, not gross; five green lights.",
  hr: "Status automation: 520 h/year × ₹1,200 = ₹6.24 L gross; minus ₹1.2 L upkeep = ₹5.04 L net; owner TA Ops; Tier 2; rollback = revert to manual digest; data cleared.", mistake: "Building before naming an owner." },
"C05.7": { l1: "Test normal, edge and failure cases, fix problems methodically, and hand over a complete evidence pack.",
  l2: "Test Normal, Edge and Failure cases; minimum pack 2 Normal, 2 Edge, 1 Failure. Debugging: Reproduce → Isolate failing step → Verify logic/conditions → Implement fallback safeguard → Retest all scenarios. Evidence Handover Package: workflow logic diagram, working build/configuration, 5 documented test cases, governance SOP (owners, SLAs, fallbacks), formal deployment sign-off.",
  take: "2-2-1 test pack; reproduce → isolate → verify → safeguard → retest; handover = diagram, build, 5 tests, SOP, sign-off.", aid: "Two normal, two edge, one failure.",
  hr: "Interview reminder tests: standard slot; candidate in another time zone; missing panel email (edges); calendar API down (failure).", mistake: "Testing only happy paths." },
/* ===== Week 6 ===== */
"C06.1": { l1: "Write one solid master document, then turn it into the formats each audience needs, without changing the numbers.",
  l2: "Single source → multi-output: a structured master document is the canonical source of truth, transformed with locked numerical figures and risk statements into a 5-slide executive deck, 1-page memo, 150-word email update, 3-bullet board brief and meeting talking points.",
  take: "One canonical master document → five audience formats with numbers and risk statements locked.", aid: "One truth, five shapes.",
  hr: "Quarterly TA review master → CHRO deck, HRBP memo, hiring-manager email, board bullets, talking points; offer-acceptance rate identical everywhere.", mistake: "Regenerating each format from scratch so the numbers drift." },
"C06.2": { l1: "Before AI makes slides, write a brief that says what the content must achieve.",
  l2: "7-Step Business Brief: Context, Objective, Audience, Decision Required, Constraints (timeframe, format, tone, slide count), Evidence Available, Sensitivity Level.",
  take: "Brief = Context, Objective, Audience, Decision Required, Constraints, Evidence Available, Sensitivity Level.", aid: "Why, what, who, decide, limits, proof, secrecy.",
  hr: "Brief for a campus-hiring budget deck: decision required = approve ₹40 L for 3 new campuses; evidence = last year's offer and retention data; sensitivity = internal.", mistake: "No 'Decision Required', so the deck informs but asks for nothing." },
"C06.3": { l1: "Check every important claim in AI-made content: where it came from and how sure you are.",
  l2: "Claims Table discipline: a presentation is incomplete without auditing at least 5 key claims. Columns: Claim Statement, Data Source, Confidence Level (High/Medium/Low), Verification Step. Any low-confidence claim without verifiable data is removed or rewritten as 'To be validated in pilot phase'.",
  l3: "Build the table while drafting, not after. Link each claim to its row in the master document (C06.1). Numbers come from source data, never from the model's memory.",
  l4: "This applies the assertion–evidence approach (course reference: Penrose & Alley): every headline is an assertion that needs evidence on the slide.",
  why: "Unsupported assertions are the fastest way to lose executive trust.", how: "List ≥ 5 claims → source → confidence → verification step → remove or reword low-confidence ones.",
  biz: "Protects your credibility as a consultant.", analogy: "Footnotes for a slide deck.",
  ex: "'AI cuts reporting time by 156 hours a year' → source: pilot timesheets → High → checked against 4 weeks of logs.",
  hr: "'Industry offer-decline rate is 18%' → no source → Low → rewrite as 'To be validated in pilot phase' or remove.",
  gen: "'Competitor X will cut prices' → single rumour → Low → remove.",
  mistakes: ["Auditing fewer than five claims", "Keeping low-confidence claims because they sound right"], risks: [],
  confused: [["C11.4", "Claims tables check content you publish; citation verification is built into an assistant's answers."]],
  tools: ["Spreadsheet claims table"], notWhen: [],
  exercise: "Take an AI-generated deck and build a five-row claims table. What did you remove or reword?",
  predict: { q: "A claim has medium confidence and a credible source. Keep it?", a: "Keep it, with the source and verification step recorded. Only low-confidence claims without verifiable data must be removed or reworded." } },
"C06.4": { l1: "Decks can refresh automatically when the data changes.", l2: "Link data to a template; AI writes commentary from the new numbers; a human reviews before sharing.", take: "Auto-updating decks = data + template + AI commentary + human review.", aid: "Template once, refresh forever.", hr: "Monthly TA review deck refreshes from the hiring tracker.", mistake: "Auto-sending decks without review." },
"C06.5": { l1: "Tell the story in seven steps and make each slide's point clear in ten seconds.",
  l2: "7-stage narrative: Current Situation → Problem/Gap → Impact (cost of inaction) → Proposed Action → Evidence → Risk & Controls → Decision Ask. The 10-Second Test: a slide's insight is clear in 10 seconds without narration. Action headlines state conclusions, not topics. At most 3 levels of visual hierarchy, with an explicit 'So What?'.",
  take: "Situation → Gap → Impact → Action → Evidence → Risk & Controls → Decision Ask; 10-second test; action headlines; ≤ 3 levels; 'So what?'.", aid: "Seven stages, ten seconds.",
  hr: "Topic title 'Offer Declines' → action headline 'Offer declines doubled in Q3 – a 10% band revision would recover 30 hires'.", mistake: "Topic titles like 'Background' and 'Data'." },
/* ===== Week 7 ===== */
"C07.1": { l1: "Dashboards are only as good as their data. Know what each row means and keep the table clean.",
  l2: "Grain: the precise real-world entity one row represents (one transaction vs a daily summary); joining tables with mismatched grains multiplies duplicates. Dataset hygiene: flat schemas (no merged cells or embedded totals), YYYY-MM-DD dates, uniform category labels, explicit null-value rules.",
  take: "Define the grain; keep tables flat, ISO-dated, consistently labelled, with explicit null rules.", aid: "One row, one thing, one format.",
  hr: "Requisition tracker: one row per requisition; candidate-stage events in a separate table; no subtotal rows.", mistake: "Mixing requisition rows and candidate rows in one table." },
"C07.2": { l1: "Combine tables either by stacking similar ones or by matching on a shared ID, then check you didn't break the numbers.",
  l2: "Append (vertical): stack tables with identical schemas over time. Join (horizontal): merge complementary attributes on unique primary keys. Post-integration sanity checks: verify row counts, confirm totals haven't inflated, explain unmatched records, manually audit 5 sample rows.",
  take: "Append same-schema tables; join on unique keys; then check row counts, totals, unmatched records and 5 sample rows.", aid: "Stack or match, then sanity-check.",
  hr: "Append monthly ATS exports; join with the offer tracker on requisition ID; total hires must not exceed the ATS count.", mistake: "Joining on names, which duplicates rows." },
"C07.3": { l1: "Every number on a dashboard should exist to trigger a decision. If nobody would act on it, it's decoration.",
  l2: "Goal → KPI → Decision → Action: every metric connects a strategic goal to a quantifiable threshold that triggers an operational action. The 5 Tests of a True KPI: Measurable (from accessible data), Decision-Linked (a breach triggers intervention), Formula Transparency (documented and replicable), Assigned Owner, Defined Refresh Cadence.",
  l3: "Goal: fill critical roles faster. KPI: median days from requisition approval to offer acceptance, critical roles (formula documented). Threshold: > 45 days. Decision: escalate sourcing strategy. Action: TA lead adds agency and referral push within 5 days. Owner: TA lead. Refresh: weekly.",
  l4: "Too many KPIs causes information overload (a dashboard failure mode). Pair speed with quality KPIs to prevent gaming. Base thresholds on historical baselines.",
  why: "It turns dashboards into decisions.", how: "Goal → KPI with formula → threshold → decision → action, then run the five tests.",
  biz: "Leaders fund dashboards that change decisions.", analogy: "A fuel warning light: measured, a set level, an obvious action, a driver who owns it.",
  ex: "Churn > 3% monthly triggers a retention campaign owned by CX, refreshed weekly.",
  hr: "Offer-acceptance rate < 80% for two months → comp benchmarking review; owner TA head; refreshed monthly; formula in the KPI dictionary.",
  gen: "Inventory days > 60 → reorder-policy review; owner supply-chain manager.",
  mistakes: ["KPIs without owners", "Vanity metrics with no decision", "Formulas nobody can replicate"], risks: ["Gaming a single KPI"],
  confused: [["C08.4", "C07.3 designs the decision rule in advance; C08.4 applies it to new insights."]],
  tools: ["Sheets", "Excel", "Looker Studio", "Power BI"], notWhen: [],
  exercise: "Turn 'improve candidate experience' into two KPIs and run each through the five tests.",
  predict: { q: "Which of the five tests does 'number of LinkedIn posts per month' usually fail?", a: "Decision-Linked: no breach would trigger a specific intervention, so it's a vanity metric." },
  cvp: "Your brief used Goal → KPI → Threshold → Decision → Action. The course writes Goal → KPI → Decision → Action and places the threshold inside the KPI ('a quantifiable threshold that triggers action'). Same logic; use the course wording in the exam." },
"C07.4": { l1: "A good dashboard tells you in ten seconds what's happening, whether it's good or bad, and what to do.",
  l2: "10-Second Decision Test. Layout: 3–6 summary KPI cards top-left/top-centre, time-series trends in the middle, segment breakdowns at the bottom. Traffic-light discipline: Green on track, Amber approaching threshold, Red breach requiring action; avoid decorative multi-colour palettes.",
  take: "10-second test; 3–6 KPI cards on top, trends in the middle, breakdowns below; Green/Amber/Red only for status.", aid: "Summary, trend, detail; traffic lights mean action.",
  hr: "TA dashboard: 5 cards (open reqs, time-to-fill, offer acceptance, pipeline coverage, HM satisfaction) with RAG status; weekly trend; breakdown by business unit.", mistake: "Using colour for decoration so red stops meaning 'act'." },
"C07.5": { l1: "Dashboards fail in predictable ways, and a handover pack keeps them alive after you build them.",
  l2: "Failure modes: information overload, vanity metrics, missing data owners, undocumented assumptions, silent pipeline failures. Dashboard Handover Package: production file, KPI dictionary (formulas, sources), refresh pipeline architecture, documented assumptions, data lineage registry, named owner and audit cadence.",
  take: "Avoid overload, vanity metrics, missing owners, hidden assumptions and silent pipeline failures; hand over with KPI dictionary, pipeline, assumptions, lineage and owner.", aid: "Document it or it dies.",
  hr: "The TA dashboard broke silently when the ATS export changed a column name; a lineage registry and refresh alert would have caught it.", mistake: "No owner after the analyst who built it leaves." },
/* ===== Week 8 (brochure only) ===== */
"C08.1": { l1: "You can give dashboard data to AI and ask what it shows.", l2: "Export a clean summary with definitions (your KPI dictionary), strip personal data, and ask for specific outputs.", take: "Connect dashboards to AI by passing clean, defined, minimal data.", aid: "Clean data in, clear insight out.", hr: "Weekly KPI table plus definitions → AI insight summary.", mistake: "Pasting raw data with candidate names." },
"C08.2": { l1: "Look for patterns (what usually happens), trends (direction over time) and anomalies (unusual jumps).", l2: "Compare against a baseline; separate one-off spikes from sustained trends; check seasonality before raising alarms.", take: "Patterns, trends and anomalies are judged against a baseline and season.", aid: "Compared with what?", hr: "Campus offers dip every March: seasonal, not an anomaly.", mistake: "Reacting to one week's spike." },
"C08.3": { l1: "AI can write the weekly summary for leaders from the numbers.", l2: "Use a fixed structure: what changed, why it matters, what to do. Week 6's claims discipline applies; a human reviews before sending (Tier 2).", take: "Leadership summaries: what changed, why it matters, what to do.", aid: "Changed, matters, do.", hr: "Monday TA brief to the CHRO.", mistake: "Listing numbers without implications." },
"C08.4": { l1: "An insight is only useful if it leads to a decision and someone acts on it.", l2: "Attach a recommended action, an owner and a deadline to every insight.", take: "Every insight needs a decision, an owner and a next step.", aid: "Insight without an owner is trivia.", hr: "'Agency hires leave faster' → review agency mix, owner TA ops, by quarter end.", mistake: "Insight reports with no actions." },
/* ===== Week 9 ===== */
"C09.1": { l1: "Competitive intelligence starts with a question you need answered, not with collecting news.",
  l2: "Systematically turn raw market signals into strategic intelligence. Process: Define Strategic Questions → Select Analysis Dimensions → Identify Signal Sources → Design Collection & Validation Process.",
  take: "CI = strategic questions → analysis dimensions → signal sources → collection & validation.", aid: "Question first, sources second.",
  hr: "'Are competitors building GenAI teams in Bengaluru?' → dimensions: roles, seniority, volume → sources: job boards, LinkedIn, press → weekly collection with validation.", mistake: "Collecting everything without a question." },
"C09.2": { l1: "Market signals fall into five families.",
  l2: "Five signal categories: Competitor Moves (launches, pricing, partnerships, key hiring, funding); Market Shifts (segment growth, demand, M&A); Technology Disruptions (patents, R&D, open-source releases); Customer Behaviour (reviews, community feedback, switching); Regulatory & Policy Updates (compliance mandates, privacy laws, trade policy).",
  l3: "For talent intelligence, the categories map cleanly: competitor hiring surges (competitor moves), skills demand (market shifts), new AI tooling changing roles (technology), candidate sentiment on Glassdoor (customer behaviour), labour codes and data-protection rules (regulatory).",
  l4: "Assign each category its own sources and cadence; regulatory signals change slowly but carry Tier 3 consequences.",
  why: "Categories make collection systematic and coverage visible.", how: "Tag every signal with one category; check no category is empty for your question.",
  biz: "A coverage checklist for any CI engagement.", analogy: "Five radar dishes pointed at different parts of the sky.",
  ex: "A rival's 30 new data-engineering roles: competitor move. A new data-privacy rule: regulatory.",
  hr: "Glassdoor reviews complaining about a rival's return-to-office mandate: customer behaviour, and a sourcing opportunity.",
  gen: "A competitor's patent filing in battery chemistry: technology disruption.",
  mistakes: ["Only tracking competitor moves", "Treating rumours as signals"], risks: [],
  confused: [["C09.3", "Categories classify signals; triangulation and the Signal Log validate and record them."]], tools: ["Job boards", "Patent databases", "Review sites"], notWhen: [],
  exercise: "Classify ten recent market signals relevant to your hiring into the five categories.",
  predict: { q: "A competitor's engineering blog announces an open-source AI recruiting tool. Category?", a: "Technology disruption (open-source release), and possibly a competitor move." } },
"C09.3": { l1: "Confirm signals from different kinds of sources, and log every one in the same format.",
  l2: "Triangulate across Primary sources (customer interviews, conferences, frontline sales feedback), Secondary sources (audited filings, annual reports, industry research) and Digital sources (job boards, code repos, patent databases). Standard Signal Log: Signal Description, Source URL, Date, Category, Credibility Score (High/Medium/Low), Validation Status, Business Relevance, Next Action (Use Now / Monitor / Discard).",
  take: "Triangulate primary, secondary and digital sources; log each signal with credibility, validation status and next action.", aid: "Three source types, one log.",
  hr: "A rumoured campus-offer hike: digital (job posting) + primary (TPO conversation) + secondary (salary survey) before 'Use Now'.", mistake: "Logging signals without a credibility score." },
"C09.4": { l1: "Compare competitors on the same fixed dimensions, and only infer strategy when several independent signals agree.",
  l2: "Fixed comparison dimensions: Products, Pricing Models, Market Verticals, Technology Architecture, Partnerships, Distribution Channels. Infer strategic intent only when multiple independent signals converge; avoid building strategy on isolated rumours.",
  take: "Compare on fixed dimensions; infer intent only from converging independent signals.", aid: "One signal is noise; three agreeing are a pattern.",
  hr: "A competitor posting AI roles + hiring an AI head + announcing an AI product = converging signals of an AI capability build.", mistake: "Acting on one LinkedIn post." },
"C09.5": { l1: "A standard eight-part brief for leaders, plus alerts for big events.",
  l2: "8-Part Executive Brief: Strategic Question, Key Signals, Context Analysis, Strategic Insights, Business Implications, Evidence Confidence Level, Decision Ask, Next Steps/Owner. Automated alert triggers for high-impact events (e.g. confirmed competitor price change ≥ 10%, unexpected acquisition).",
  take: "Brief = question, signals, context, insights, implications, confidence, decision ask, next steps/owner; predefined alert triggers.", aid: "Eight parts, one decision.",
  hr: "Alert trigger: a competitor's confirmed campus offer ≥ 10% above our band.", mistake: "Briefs with no evidence-confidence level or decision ask." },
/* ===== Week 10 ===== */
"C10.1": { l1: "Decide exactly what the assistant may and may not do, and how you'll know it's working.",
  l2: "Allowed vs Prohibited boundaries (e.g. allowed to summarise HR policies; prohibited from giving binding legal counsel). Measurable success criteria: Accuracy (grounded in source), Format Compliance, Time Efficiency (< 30 seconds), User Satisfaction (≥ 4/5).",
  take: "Write explicit allowed and prohibited lists; success = accuracy, format compliance, < 30 s, satisfaction ≥ 4/5.", aid: "Allowed, prohibited, measured.",
  hr: "Recruiter assistant: allowed to explain interview process and draft messages; prohibited from salary negotiation, legal advice and decisions on candidates.", mistake: "An assistant that 'helps with all of HR'." },
"C10.2": { l1: "Give the assistant three kinds of context, and a prompt pattern that forces it to stick to its sources.",
  l2: "Context layers: Static (canonical SOPs, product specs), Dynamic (runtime user input, live API session data), System (persona, tone, operating rules). Grounded prompt pattern: Role + Source of Truth + Task + Evidence Rule + Missing Context Rule + Output Schema.",
  take: "Static, dynamic and system context; grounded prompt = Role + Source of Truth + Task + Evidence Rule + Missing Context Rule + Output Schema.", aid: "Three layers, six-part grounding.",
  hr: "Policy assistant: static = leave policy; dynamic = employee's question and location; system = HR Ops persona; Evidence Rule = cite section; Missing Context Rule = ask for location if absent.", mistake: "No Missing Context Rule, so the assistant guesses." },
"C10.3": { l1: "Set how the assistant sounds and what it remembers.", l2: "Write a style guide (System context); define what to remember (preferences) and what never to store (personal data).", take: "Tone, style and memory rules make assistants consistent and safe.", aid: "Remember preferences, never personal data.", hr: "Remembers a hiring manager's preferred format; never stores candidate details between sessions.", mistake: "Unlimited memory." },
"C10.4": { l1: "Put four kinds of guardrail around the assistant, and run its work through a fixed sequence with a human check.",
  l2: "Four guardrail layers: Input Validation, Output Constraints, Content Safety Filters, Escalation Triggers. Multi-step workflow: Input Collection → Draft Generation → Safety Validation → Human Handoff / Review → Final Execution.",
  l3: "Input validation rejects missing or unsafe inputs (e.g. PII pasted by users); output constraints enforce format and scope; safety filters block harmful or discriminatory content; escalation triggers hand over to a human (sensitive topics, low confidence, angry users). Human handoff sits before any Tier 3 execution.",
  l4: "Layers overlap deliberately; a single filter will miss something. Too many escalations make the assistant useless; tune triggers with the test pack.",
  why: "Guardrails make assistants safe to put in front of employees and candidates.", how: "Define each layer → place them in the workflow → test with adversarial cases.",
  biz: "Lets you deploy assistants in sensitive HR contexts.", analogy: "Airport security: check-in, screening, gate check, and staff who step in.",
  ex: "Customer-success assistant: validates account ID, constrains answers to the help centre, filters abusive content, escalates refund requests.",
  hr: "Candidate FAQ assistant: rejects uploads of ID documents (input), answers only from published FAQs (output), filters discriminatory content (safety), escalates salary negotiation and complaints (escalation).",
  gen: "Sales assistant escalates any discount request above policy.",
  mistakes: ["Only an output filter", "No escalation trigger"], risks: ["Over-escalation making the assistant pointless"],
  confused: [["C10.1", "Boundaries define scope; guardrail layers enforce it."]], tools: ["Custom GPT instructions", "Moderation filters", "Automation approval steps"], notWhen: [],
  exercise: "Write one rule per guardrail layer for a candidate FAQ assistant.",
  predict: { q: "A candidate pastes their passport scan into the chat. Which layer should catch it?", a: "Input Validation: reject or redact personal documents before processing." } },
"C10.5": { l1: "Test the assistant with five planned cases and score them. Any weak or unsafe result blocks launch.",
  l2: "Standard 5-Case Test Pack: 3 Normal, 1 Boundary/Edge, 1 Adversarial/Failure. Score each case 1–5 on Functional Accuracy, Clarity, Relevance, Format Adherence, Safety. Any case scoring < 3, or any safety failure, blocks production.",
  take: "3 normal, 1 boundary, 1 adversarial; score 1–5 on accuracy, clarity, relevance, format, safety; < 3 or a safety fail blocks production.", aid: "3-1-1, and three is the floor.",
  hr: "Intake assistant: 3 normal requisitions, 1 vague brief (boundary), 1 request for competitor salaries (adversarial).", mistake: "Averaging scores so one unsafe answer is hidden." },
"C10.6": { l1: "Know what to do when the assistant fails, and improve it in four versions.",
  l2: "Failure Escalation Matrix: Hallucination → stop output immediately, audit source grounding, disallow continuation; Instruction Drift → correct prompt constraints, re-run under reviewer oversight; Missing Context → prompt the user for missing documents, do not guess. Version maturation: V1 Baseline → V2 Grounded Context → V3 Structured Workflows → V4 Validated Production.",
  take: "Hallucination: stop and audit; drift: correct and re-run under review; missing context: ask, don't guess. V1 Baseline → V2 Grounded → V3 Structured → V4 Validated.", aid: "Stop, correct, ask; then version up.",
  hr: "The intake assistant invents a budget figure: stop, audit grounding, block until fixed.", mistake: "Letting a hallucinating assistant continue with a disclaimer." },
/* ===== Week 11 ===== */
"C11.1": { l1: "Before answering, the AI looks up the right page in your documents, like an open-book exam.",
  l2: "Retrieve First, Then Answer: anchor responses in verified company records rather than pre-trained memory. It combines semantic-search retrieval precision with LLM synthesis fluency.",
  l3: "Decide per use case: public and stable knowledge (a prompt may do), private or changing knowledge (retrieve), live transactional data (integrate via API). Then design retrieval: knowledge base, chunking, metadata filters, citation and rejection rules.",
  l4: "Long-context models can read whole documents, reducing the need for retrieval on small sets, but cost more per query and don't solve permissions (RBAC) or freshness on large collections.",
  why: "Most business questions are about private, changing information the model has never seen.", how: "Question → retrieve relevant chunks → answer only from them → cite.",
  biz: "Policy, SOP and product-knowledge assistants all rest on it.", analogy: "An open-book exam: look it up, then answer.",
  ex: "IT helpdesk assistant answers from current SOPs instead of generic advice.",
  hr: "'Can we pay a joining bonus for an L5 role in Pune?' → retrieves Compensation Guidelines v3.2 §4 and answers with the citation, or 'Information not available in knowledge base'.",
  gen: "Sales asks about contract terms → retrieves the current master service agreement clause.",
  mistakes: ["Uploading everything 'just in case'", "No rejection rule, so the model fills gaps"], risks: ["Outdated documents produce confident wrong answers"],
  confused: [["C10.2", "Static context is loaded into every conversation; retrieval fetches only the relevant chunks per question."]],
  tools: ["Custom GPTs", "Claude Projects", "NotebookLM", "Flowise"], notWhen: ["Creative drafting with no factual source", "Live transactional data — use an integration"],
  exercise: "List five questions recruiters ask you weekly. For each: prompt alone, retrieval, or live integration?",
  predict: { q: "'How many offers did we release this week?' Retrieval or integration?", a: "Integration: live transactional data from the ATS, not document knowledge." } },
"C11.2": { l1: "RAG has three steps: find the relevant text, add it to the question, and let the AI answer from that text.",
  l2: "A document-grounded assistant combines semantic search (finding chunks by meaning) with LLM synthesis. Query → retrieve top chunks (after metadata filtering) → augment the prompt → generate with citations.",
  l3: "Failure points: wrong or outdated document (governance), right document not retrieved (chunking or metadata), retrieved but misread (generation), no rejection rule (hallucination). Test retrieval separately from answers.",
  l4: "Chunk size trades precision for context; hybrid keyword + semantic search and reranking improve precision at a latency cost (ALLIED).",
  why: "It is the standard architecture for trustworthy document-based assistants.", how: "Prepare KB → filter by metadata → semantic ranking → grounded generation → citation.",
  biz: "Fast to deploy over existing documents; updating knowledge means updating documents, not models.", analogy: "A research assistant who pulls the right pages before you write.",
  ex: "Support bot over product manuals.", hr: "Recruiter policy assistant over relocation, joining-bonus and referral rules.", gen: "Legal team assistant over contract templates.",
  mistakes: ["Blaming the model when retrieval failed"], risks: ["Indirect prompt injection through documents", "Access leaks if retrieval ignores RBAC"],
  confused: [["fine-tuning", "Fine-tuning changes model behaviour; it isn't a reliable way to add facts."]], tools: ["Flowise", "NotebookLM", "Custom GPTs", "Vector databases"], notWhen: ["A two-page document (paste it)"],
  exercise: "Draw the pipeline for an HR policy assistant and mark the four failure points with one test question each.",
  predict: { q: "The assistant cites the 2023 relocation policy for a 2025 question. Which stage failed?", a: "Knowledge-base governance: a superseded document is still indexed. Retire it and trigger an index refresh." },
  allied: [{ t: "Embeddings & vector search", s: "Text turned into numeric vectors so passages with similar meaning are found even with different words; this is the 'semantic search' in the course's definition.", src: "ALLIED" }] },
"C11.3": { l1: "Clean up the documents, cut them into self-contained pieces, and label every piece.",
  l2: "Document cleaning: remove duplicate files, retire superseded drafts, standardise formatting and headings, establish canonical sources of truth. Semantic chunking: self-contained chunks, each covering a single complete concept (200–500 words). Metadata on every chunk: Document Title, Department, Version Date, Owner, Access Clearance, used to filter before semantic ranking.",
  l3: "Chunk along headings so a chunk answers one question. Metadata filters (department, version date, access clearance) narrow the candidate set before semantic ranking, which prevents 'right policy, wrong country' and access leaks.",
  l4: "Chunks under ~200 words lose context; over ~500 dilute relevance. Tables and lists need special handling so rows aren't split from headers.",
  why: "Retrieval quality is decided before any question is asked.", how: "Clean → chunk 200–500 words per concept → tag five metadata fields → index.",
  biz: "Most RAG failures are document-preparation failures.", analogy: "Library cataloguing: one book per shelf slot, labelled by subject, date and who may borrow it.",
  ex: "A 40-page travel policy becomes 60 chunks, each one rule with title, department, version date, owner and clearance.",
  hr: "Relocation Policy India v5 and UAE v2 chunked separately and tagged by country so the assistant never mixes them.",
  gen: "Product manuals chunked by procedure.",
  mistakes: ["Indexing drafts alongside approved versions", "Chunks that split a rule from its exceptions"], risks: ["Missing access-clearance tags leaking restricted content"],
  confused: [["C11.5", "C11.3 prepares the knowledge base; C11.5 keeps it current and controlled."]], tools: ["Flowise", "NotebookLM", "Document editors"], notWhen: [],
  exercise: "Take one HR policy and mark where you'd split it into 200–500-word chunks; write the five metadata fields for two chunks.",
  predict: { q: "Which metadata field stops a recruiter retrieving compensation-band maxima?", a: "Access Clearance, enforced by role-based access control." } },
"C11.4": { l1: "Make the AI show exactly where each answer came from, and say plainly when the documents don't cover the question.",
  l2: "Granular citations at document, section or chunk level (e.g. [Travel Policy v3.2, Section 4.2]). Strict retrieval constraints: generation limited to retrieved excerpts. Mandatory rejection of unknowns: 'Information not available in knowledge base' rather than speculation. Enforced structure: Answer + Source Citation schema.",
  l3: "The rejection phrase is part of the output schema, which makes it testable: include unanswerable questions in every test pack and expect the exact phrase.",
  l4: "Citations can be wrong too (a real section cited for a claim it doesn't make). Spot-check faithfulness; for Tier 3 answers, quote the exact sentence.",
  why: "Citations make answers auditable; rejection stops invention.", how: "Strict constraint + granular citation + rejection phrase + Answer/Source schema.",
  biz: "Reduces the risk of wrong policy statements reaching employees or candidates.", analogy: "A footnoted report, not an opinion.",
  ex: "'Economy class applies to flights under 6 hours [Travel Policy v3.2, Section 4.2].'", hr: "'Information not available in knowledge base. Please contact Global Mobility.'", gen: "Customer support citing the warranty clause.",
  mistakes: ["Trusting a citation without opening it", "A rejection message that varies, so tests can't check it"], risks: ["False confidence from wrong citations"],
  confused: [["C06.3", "C06.3 audits claims in content you publish; C11.4 builds citation into an assistant's answers."]], tools: ["NotebookLM", "Custom GPTs", "Claude Projects"], notWhen: [],
  exercise: "Write the grounding instruction for a policy assistant: constraint, citation format, rejection phrase and output schema.",
  predict: { q: "The question isn't covered by any retrieved chunk. What exactly should the assistant say?", a: "'Information not available in knowledge base', optionally with who to contact. No speculation." } },
"C11.5": { l1: "Someone must keep the knowledge base current and control who can see what.",
  l2: "Version control with audit trails (Draft → Reviewed → Approved). Index refresh triggers: re-index and regenerate embeddings whenever source documents are modified or archived. Role-based access control (RBAC): least-privilege access so users only retrieve within their clearance.",
  take: "Version control Draft → Reviewed → Approved; refresh the index on every change; enforce RBAC.", aid: "Approve, refresh, restrict.",
  hr: "Compensation guidelines visible only to comp team and TA leads; updated policy triggers re-indexing the same day.", mistake: "Updating a policy without re-indexing, so the assistant keeps citing the old one." },
/* ===== Week 12 ===== */
"C12.1": { l1: "Search across several kinds of sources at once, but decide first which questions and sources are in scope.",
  l2: "Unify search across unstructured text (PDFs, SOPs), structured data (warehouses, sheets), live APIs and external feeds. Define explicit scope: permitted question types, authorised sources, out-of-scope exclusions.",
  take: "Multi-source search spans documents, structured data, APIs and external feeds, within an explicit scope.", aid: "Many sources, one scope.",
  hr: "Compensation search: salary-survey PDFs, internal offer sheet, ATS API, job-board feed; out of scope: individual employees' pay.", mistake: "Connecting everything without a scope." },
"C12.2": { l1: "Either send each question to the single best source, or ask several sources at once and combine the answers.",
  l2: "Query Routing: intent classification sends the query to one optimal repository; maximises speed, reduces compute. Parallel Retrieval: queries multiple systems concurrently and aggregates downstream; maximises coverage at the cost of higher latency.",
  take: "Routing = one best source, fast and cheap; parallel = many sources, more coverage, more latency.", aid: "Route for speed, fan out for coverage.",
  hr: "'What's our referral bonus?' → route to policy KB. 'What's the market rate for data scientists?' → parallel across survey, offers and job boards.", mistake: "Parallel retrieval for every simple question." },
"C12.3": { l1: "Remove repeats, put everything in the same units and definitions, then rank what's left.",
  l2: "Deduplication: filter exact duplicates and merge near-identical snippets. Normalisation: standardise schemas, currencies, date formats and conflicting metric definitions (e.g. Gross vs Net Revenue) before verification. Composite ranking: Score = w1·Relevance + w2·Recency + w3·Source Credibility + w4·Completeness.",
  take: "Dedupe, normalise (units, dates, definitions), then rank by weighted relevance, recency, credibility and completeness.", aid: "Clean, align, rank.",
  hr: "Salary figures in CTC vs fixed pay, LPA vs monthly, 2024 vs 2025 must be normalised before comparison; survey data gets high credibility weight.", mistake: "Comparing CTC from one source with fixed pay from another." },
"C12.4": { l1: "When sources disagree, trust them in a set order, and if it's still unclear, say so.",
  l2: "Evidence hierarchy: Internal Authoritative Sources > External Official Filings > Recent Secondary Reports > Unverified Web Sources. Resolution rules: (1) select the highest-ranked authoritative source, (2) present both transparently with context if ambiguity persists, (3) prompt the user for clarification, or (4) reject if uncertain.",
  l3: "Contradictions arise between outdated and current files, internal and external feeds, and policy vs actual practice. Normalise first (C12.3); many 'conflicts' are definition differences.",
  l4: "Internal sources rank highest for internal facts but not always for market facts: an internal offers sheet describes your offers, not the market. Apply the hierarchy to the question being asked.",
  why: "Without a rule, the assistant picks whichever source it read last.", how: "Normalise → apply hierarchy → disclose, clarify or reject.",
  biz: "Defensible answers when executives ask 'where did this number come from?'", analogy: "A court weighing sworn testimony above hearsay.",
  ex: "Company annual report vs a news article on revenue: the official filing wins.",
  hr: "Internal policy says 15 days' notice buy-out; a recruiter's old email says 30: internal authoritative (current policy) wins.",
  gen: "Vendor price on contract vs price on a blog: the contract wins.",
  mistakes: ["Averaging conflicting numbers", "Hiding the conflict from the user"], risks: [],
  confused: [["C09.3", "CI triangulation validates signals; the evidence hierarchy resolves contradictions in answers."]], tools: [], notWhen: [],
  exercise: "Two sources disagree on the median data-science graduate offer. Apply the hierarchy and the four rules.",
  predict: { q: "Ambiguity remains after applying the hierarchy. What's the next rule?", a: "Present both transparently with context; if that won't do, ask the user to clarify or reject." } },
"C12.5": { l1: "Watch how the search assistant is used and performing, and protect sensitive data.",
  l2: "Log all queries, source retrievals, generated outputs and failure rates. Configure threshold alerts for significant data shifts or metric deviations. Enforce source-level access control, sensitivity classification (Public, Internal, Confidential, Restricted) and PII masking.",
  take: "Log queries, retrievals, outputs and failures; alert on shifts; control access; classify Public/Internal/Confidential/Restricted; mask PII.", aid: "Log, alert, classify, mask.",
  hr: "Alert when compensation queries spike after a competitor announcement; mask candidate names in logs.", mistake: "No failure-rate logging, so silent retrieval failures go unnoticed." },
/* ===== Week 13 ===== */
"C13.1": { l1: "A chatbot talks. An assistant helps with a role using context. An automation follows fixed steps. An agent works toward a goal and decides its own steps using tools. A multi-agent system is several agents with different jobs working together.",
  l2: "The differences are autonomy and action. Automations are predictable; agents are flexible but less predictable and sit at the 'Agent Frameworks: high governance needed' end of the Business AI Stack (C02.7). Choose the least autonomous design that solves the problem.",
  l3: "Agent = model + instructions + tools + state + a loop (plan → act → check) + stop condition. Automation = fixed layers (C05.2). Assistant = role + context layers + guardrails, responding to a user. Multi-agent = several agents with defined roles and handoffs (C13.2).",
  l4: "Agents add value when steps vary by situation; they cost more tokens and latency, are harder to test and need least-privilege permissions and approvals.",
  why: "Choosing the wrong pattern is the most expensive design mistake.", how: "Ask: are the steps fixed? Does it act in systems? Does it pursue a goal across steps?",
  biz: "Lets you explain why you didn't build an 'agent' when an automation was enough.", analogy: "Receptionist, personal assistant, conveyor belt, project manager, project team.",
  ex: "Weekly report emailed every Monday = automation. Research a new market and draft a recommendation = multi-agent.",
  hr: "Policy Q&A = assistant. Interview reminders = automation. Find slots across five calendars, handle conflicts, propose times = agent.",
  gen: "Invoice reminders = automation; procurement agent chasing quotes within limits = agent.",
  mistakes: ["Calling every chatbot an agent", "Building an agent for fixed steps"], risks: ["Excessive autonomy without approval"],
  confused: [["C05.2", "Automations follow fixed layers; agents choose their next step."]], tools: ["n8n", "Flowise", "Agent SDKs"], notWhen: ["Fixed, repeatable steps"],
  exercise: "Classify: FAQ bot; Monday pipeline email; intake-brief assistant; bot that sources, messages and books screens; planner + researchers + writer producing a market report.",
  predict: { q: "A bot reads new CVs and moves strong ones to the next ATS stage by fixed rules. Which is it?", a: "An automation (fixed rules). It affects candidates, so it's Tier 3 and needs human review." },
  cvp: "This five-way distinction comes from your brief (IITM-L). The compendium frames the same idea through the Business AI Stack and the statement that monolithic models degrade on multi-step work." },
"C13.2": { l1: "Split a big AI job into roles, like a team: one plans, one researches, one does the work, one checks it.",
  l2: "Monolithic models degrade when asked to research, analyse, format and review in one prompt. Decompose into specialised roles: Planner (deconstructs goals into sequential tasks, sets priorities), Researcher (retrieves data from approved sources), Executor (core transformations, drafts or API actions), Reviewer/Validator (audits outputs against schema, factual grounding and safety rules). Golden rule: one agent = one clear, unambiguous responsibility.",
  l3: "Each role has defined input, output schema and tool permissions (C13.6). The Reviewer checks claims against the Researcher's citations, the output schema and safety rules before human review.",
  l4: "Every extra agent adds handoffs, cost and latency (Quality–Cost–Time triangle, C13.9). Prune roles that always run together; split only where instructions, tools or review independence differ.",
  why: "Clear roles make multi-agent systems controllable and debuggable.", how: "List the work → group into responsibilities → one agent per responsibility → define I/O and tools.",
  biz: "Mirrors how consulting teams work, which makes it easy to explain.", analogy: "A newsroom: editor assigns, reporters research, writer drafts, sub-editor checks.",
  ex: "Market report: Planner → Researchers → Executor (draft) → Reviewer.",
  hr: "Talent-market study: Planner sets sub-questions; Researcher gathers salary, supply and competitor data; Executor drafts the brief; Reviewer checks every figure against sources.",
  gen: "Competitor product launch analysis with the same roles.",
  mistakes: ["Two agents with overlapping jobs", "A Reviewer with no checklist"], risks: ["Unsupported claims slipping through handoffs"],
  confused: [["C13.4", "C13.2 defines who does what; C13.4 defines what they pass to each other."]], tools: ["n8n", "Flowise", "Agent frameworks"], notWhen: ["A single prompt or agent with a clear task works"],
  exercise: "Decompose 'Should we open a hiring hub in Coimbatore?' into Planner, Researcher, Executor and Reviewer with one responsibility each.",
  predict: { q: "Why do monolithic prompts degrade on research-plus-writing-plus-review tasks?", a: "One context juggles conflicting instructions and grows too long; quality, format and checking all slip. Decomposition gives each role focused instructions." } },
"C13.3": { l1: "Agents can work one after another (sequential) or at the same time (parallel), with an aggregator combining the results.",
  l2: "Sequential workflows: Agent A's output becomes Agent B's structured input via defined schemas (JSON/Markdown). Parallel workflows: independent agents run subtasks concurrently; results are merged by an aggregator agent.",
  take: "Sequential = A's structured output feeds B; parallel = independent agents, merged by an aggregator.", aid: "Depends on it? Line up. Independent? Fan out, then aggregate.",
  hr: "Three Researchers in parallel (salary, talent supply, competitors) → aggregator → Executor drafts.", mistake: "Parallel agents with no aggregator, so contradictions reach the user." },
"C13.4": { l1: "Pass agents a clear, structured package with only what they need, not the whole conversation.",
  l2: "Shared context management: pass forward task state, source citations and operating constraints while excluding irrelevant history to prevent context overflow. Handoffs use defined schemas (JSON/Markdown).",
  l3: "Example Researcher → Executor schema: {task_id, findings:[{claim, source_url, date, credibility}], constraints:[], open_questions:[]}. Validate on receipt; reject incomplete handoffs.",
  l4: "Passing full transcripts wastes tokens and spreads errors; passing too little loses evidence. Citations must travel with claims so the Reviewer can check them.",
  why: "Most multi-agent failures happen at handoffs.", how: "Define schema → include state, citations, constraints → exclude irrelevant history → validate.",
  biz: "Makes multi-agent systems auditable.", analogy: "A hospital shift handover on a standard form.",
  ex: "Planner → Researcher: {sub_question, sources_allowed, deadline}.", hr: "Researcher → Executor for the hiring-hub brief carries each salary figure with its source.", gen: "Order agent → billing agent: {order_id, items, amount, approvals}.",
  mistakes: ["Prose handoffs", "Dropping citations at handoff"], risks: ["Context overflow and lost evidence"],
  confused: [["C03.5", "C03.5 structures one model's output; C13.4 applies that to agent-to-agent passing."]], tools: ["JSON schemas", "n8n", "Flowise"], notWhen: [],
  exercise: "Write the handoff schema from Researcher to Executor for a competitor-hiring study.",
  predict: { q: "The final brief cites a figure no Researcher found. Which handoff rule was broken?", a: "Claims must travel with their citations; the Reviewer should reject any claim without a source." } },
"C13.5": { l1: "MCP (Model Context Protocol) is a standard plug that lets AI connect to files, apps and data safely.", l2: "Instead of custom connections for every tool, MCP gives a common way to expose tools and data to AI, with scoped access (brochure: 'safe file access and data fetching').", take: "MCP is a standard protocol for connecting AI to tools and data with controlled access.", aid: "USB-C for AI tools.", hr: "An agent reads a shared requisition folder via MCP with read-only access.", mistake: "Granting write access 'for convenience'." },
"C13.6": { l1: "Give each agent only the tools its job needs, and require approval before it does anything consequential.",
  l2: "Least-privilege tool access: permissions follow the role (Researcher read-only database access; Executor scoped API write access). Guardrails for accuracy and permissions; approval before consequential actions.",
  take: "Permissions by role: Researcher read-only, Executor scoped write, approval before consequential actions.", aid: "Read freely, write with permission.",
  hr: "Scheduling Executor may create tentative holds; sending candidate invites needs recruiter approval; Researcher can't touch the ATS.", mistake: "Giving every agent every tool." },
"C13.7": { l1: "All agents should sound consistent and share the right facts.", l2: "Shared style guide and shared task state; private scratch work stays private.", take: "Consistent tone and shared state across agents.", aid: "One voice, shared facts.", hr: "All candidate-facing outputs use the employer-brand voice guide.", mistake: "Each agent with its own tone." },
"C13.8": { l1: "Multi-agent systems fail in four typical ways, each with a standard safeguard.",
  l2: "Infinite loops (circular handoffs, no termination; token burn with no output) → hard iteration limits (N ≤ 5) and circuit breakers. Task misrouting (ambiguous intent classification; agent gets tasks outside its capability) → explicit classification tags and strict fallback routing. Contradictory outputs (parallel branches with conflicting context) → mandatory synthesis agent with evidence-ranking rules. Missing outputs / dead ends (a step times out or fails silently; workflow stalls) → step-level timeouts and automated manual fallback routing.",
  l3: "Build the safeguards in from the start: every loop has a counter, every route a fallback, every parallel branch an aggregator, every step a timeout. The synthesis agent can reuse Week 12's evidence hierarchy.",
  l4: "Circuit breakers and fallbacks should notify an owner (Week 5 fallback ladder) rather than fail silently.",
  why: "Agent failures are expensive (token burn) and quiet unless designed for.", how: "For each failure mode, add the matching safeguard and test it.",
  biz: "Turns agent pilots into something operations will accept.", analogy: "Fuses, signposts, a referee and alarm clocks.",
  ex: "Writer and Reviewer bounce a draft back and forth forever → N ≤ 5 then route to a human.",
  hr: "Salary Researcher and job-board Researcher report different medians → synthesis agent applies the evidence hierarchy.",
  gen: "Planner sends a pricing question to the HR researcher → classification tags and fallback routing.",
  mistakes: ["No iteration limit", "No aggregator for parallel branches"], risks: ["Runaway token costs"],
  confused: [["C05.4", "The fallback ladder handles step failures; C13.8 adds agent-specific failures like loops and misrouting."]], tools: ["n8n loop limits", "Timeout settings"], notWhen: [],
  exercise: "For a 4-agent research pipeline, write the safeguard for each failure mode.",
  predict: { q: "Token costs spike and no output appears. Which failure mode, and which safeguard?", a: "An infinite loop: enforce a hard iteration limit (N ≤ 5) and a circuit breaker." } },
"C13.9": { l1: "Trace every step so you can find what broke, trim the system so it's cheaper and faster, and document it for handover.",
  l2: "Trace-driven debugging fields: Trace ID, Agent Name, Tool Invoked, Input Payload, Output Schema, Latency, Error Status. Optimise the Quality–Cost–Time triangle: prune unnecessary agents, sharpen prompts to cut token waste, cache static retrievals, batch API calls. Handover runbook: agent roles & scope, I/O schemas, execution sequence diagram, tool permissions, governance fallbacks, HITL review gates.",
  take: "Trace (ID, agent, tool, input, output schema, latency, error); prune, sharpen, cache, batch; hand over with a runbook.", aid: "Trace it, trim it, document it.",
  hr: "The trace shows the Researcher took 40 s calling an excluded source; fix the source list and cache the salary survey.", mistake: "Changing prompts without reading the trace." },
/* ===== Week 14 (brochure only) ===== */
"C14.1": { l1: "Responsible AI means AI that is fair, safe, transparent, private and has someone accountable for it.", l2: "Identify ethical risks early: who could be harmed, how, and what controls apply. The 3-Tier risk model (C01.5) and NIST AI RMF (course reference) give structure. Week 14 class material: not currently available.", take: "Responsible AI principles: fairness, accountability, transparency, safety, privacy.", aid: "Who could be harmed, and who is accountable?", hr: "AI interview analysis could disadvantage non-native speakers.", mistake: "Treating ethics as a final checkbox." },
"C14.2": { l1: "AI can repeat unfair patterns from past data. Check for bias, protect privacy and get consent.", l2: "Watch for proxy variables (college, postcode, career gaps), test outcomes by group, and limit data to what's needed.", take: "Bias safeguards: check data, proxies and outcomes by group; protect privacy and consent.", aid: "Past patterns can be past prejudice.", hr: "A screening model trained on past hires favours a few colleges.", mistake: "Removing gender but keeping proxies for it." },
"C14.3": { l1: "Protect personal and confidential data when using AI.", l2: "Minimise data, use approved tools, control retention. Applies Week 4's data sensitivity tiers and Week 12's classification (Public, Internal, Confidential, Restricted).", take: "Data protection: minimise, anonymise, approved tools, controlled retention.", aid: "Least data, approved place, limited time.", hr: "Candidate data only in the enterprise tenant.", mistake: "Using personal AI accounts for work data." },
"C14.4": { l1: "A person checks AI outputs at the right points before they cause harm.",
  l2: "Human-in-the-loop means designed review points: who checks, what they check and their authority to approve, edit or reject. The course embeds it throughout: Tier 2 and Tier 3 reviews (Week 1), approval gates and the HITL Control Matrix (Week 5), human handoff in assistants (Week 10), review gates in multi-agent runbooks (Week 13).",
  l3: "Patterns: approve-before-action (Tier 3 external messages and decisions), review-by-exception (low-confidence or flagged outputs), sampling audits (Tier 1 and 2). Give reviewers the sources, not just the output.",
  l4: "Automation bias makes reviewers approve without reading; counter with checklists, sampling of approved items and edit-rate monitoring. Too many review points erode ROI and add latency.",
  why: "The main control for medium- and high-risk AI uses.", how: "Identify harm points → choose review pattern → name reviewer → give evidence → log decision.",
  biz: "Lets organisations adopt AI in sensitive processes responsibly.", analogy: "A pilot monitoring autopilot and taking over at critical moments.",
  ex: "AI drafts refund responses; amounts above a threshold need a supervisor.",
  hr: "AI summarises candidate evidence; the hiring manager decides; rejections are reviewed by a recruiter.", gen: "AI flags suspicious invoices; a finance analyst decides.",
  mistakes: ["Review steps with no checklist", "Reviewers without source evidence"], risks: ["Rubber-stamping"],
  confused: [["C01.5", "The tier decides how much oversight; HITL design decides how the review works."]], tools: ["Approval steps in n8n/Make", "Review queues"], notWhen: [],
  exercise: "Place human review points on a candidate follow-up automation and justify each with its tier.",
  predict: { q: "Recruiters approve 99% of AI-drafted rejection emails without edits. Good news?", a: "Maybe not: it can signal rubber-stamping. Sample approved emails and measure review quality." } },
"C14.5": { l1: "Before AI goes live, prove it works, set up logging and monitoring, and know what to do when it fails.", l2: "Production readiness pulls together the course's gates: Go/No-Go (Week 5), the 5-case production gate (Week 10), KB governance (Week 11), monitoring (Week 12) and runbooks (Week 13).", take: "Production readiness: tested, logged, monitored, auditable, owned, with an incident plan.", aid: "Tested, tracked, owned.", hr: "Go-live checklist for the policy assistant.", mistake: "A pilot quietly becoming production without checks." },
"C15.1": { l1: "The capstone joins an assistant, a knowledge base and automations into one working solution.", l2: "Integrate pieces you built across the programme around one business problem.", take: "Integrated solution: assistant + knowledge base + automations in one workflow.", aid: "Join the pieces around one problem.", hr: "Recruitment operations assistant with policy RAG and status automations.", mistake: "Showing three disconnected demos." },
"C15.2": { l1: "Solve a complete, real business problem end to end.", l2: "Problem → design → build → test → measure. Start from a 1-page proposal (C01.9).", take: "End-to-end problem solving from problem definition to measured result.", aid: "Real problem, real measure.", hr: "Reduce hiring-manager status queries by half.", mistake: "Choosing a problem with no measurable outcome." },
"C15.3": { l1: "Write guides so someone else can run and maintain your solution.", l2: "Reuse the course's handover packages: Week 5 Evidence Handover, Week 7 Dashboard Handover, Week 13 runbook.", take: "Handover guides and SOPs make solutions sustainable.", aid: "If only you can run it, it isn't finished.", hr: "SOP for the TA ops team.", mistake: "No documentation." },
"C15.4": { l1: "Show the solution working and the difference it made.", l2: "Demo plus impact report: baseline, result, hard and soft ROI, risks.", take: "Demo + impact report with before/after metrics.", aid: "Show it, prove it.", hr: "Five-minute demo with hours saved and query reduction.", mistake: "Demo without numbers." }
};

